import os
import glob
from collections import OrderedDict

def parse_spring_factories(filepath):
    """Parse spring.factories using Java properties-style line continuation"""
    sections = OrderedDict()
    with open(filepath) as f:
        raw = f.read()

    # Process line continuations (backslash at end of line)
    # Join lines ending with \ with the next line
    lines = raw.split('\n')
    joined_lines = []
    i = 0
    while i < len(lines):
        line = lines[i]
        while line.rstrip().endswith('\\'):
            # Remove the trailing backslash and join with next line
            line = line.rstrip()[:-1]  # Remove the backslash
            i += 1
            if i < len(lines):
                # Preserve leading whitespace of continuation line
                next_line = lines[i]
                line = line + next_line
            else:
                break
        joined_lines.append(line)
        i += 1

    # Now parse key=value from joined lines
    for line in joined_lines:
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        if '=' in line:
            key, _, val = line.partition('=')
            key = key.strip()
            val = val.strip()
            if key not in sections:
                sections[key] = []
            if val:
                # Split by comma
                parts = [p.strip() for p in val.split(',') if p.strip()]
                for p in parts:
                    if p not in sections[key]:
                        sections[key].append(p)
    return sections

# Collect all spring.factories
merged = OrderedDict()
jar_dirs = sorted(glob.glob('/tmp/jarextract/jar_*'))
for d in jar_dirs:
    sf = os.path.join(d, 'META-INF/spring.factories')
    if os.path.exists(sf):
        sections = parse_spring_factories(sf)
        for section, values in sections.items():
            if section not in merged:
                merged[section] = []
            for v in values:
                if v not in merged[section]:
                    merged[section].append(v)

# Verify key sections
for section in ['org.springframework.context.ApplicationContextInitializer',
                'org.springframework.context.ApplicationListener',
                'org.springframework.boot.sql.init.dependency.DependsOnDatabaseInitializationDetector']:
    if section in merged:
        vals = merged[section]
        print(f"{section}: {len(vals)} entries")
        for v in vals:
            print(f"  - {v}")
    else:
        print(f"{section}: NOT FOUND")
    print()

# Write merged file
os.makedirs('/tmp/uberjar/META-INF/spring', exist_ok=True)
with open('/tmp/uberjar/META-INF/spring.factories', 'w') as f:
    for section in merged:
        values = merged[section]
        if not values:
            continue
        if len(values) == 1:
            f.write(f"{section} = {values[0]}\n")
        else:
            f.write(f"{section} = \\\n")
            for i, v in enumerate(values):
                trailing = ",\\" if i < len(values) - 1 else ""
                f.write(f"{v}{trailing}\n")
        f.write("\n")

print("Done writing merged spring.factories")
